package com.bank.refval;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class PalindromePartitionDemo {

    private static final Logger log = Logger.getLogger(PalindromePartitionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Reference Code Segmenter (Palindrome Partition)");
        ReferenceSegmenter seg = new ReferenceSegmenter();
        seg.partition("aab").forEach(p -> log.info("Segmentation: " + p));
    }
}
```

